def list_users(page: int, page_size: int) -> tuple[list[dict], int]:
    all_users = store.list_users()
    total = len(all_users)
    start = (page - 1) * page_size
    end = start + page_size
    return all_users[start:end], total

def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_list_users(params: dict) -> tuple[int, dict]:
    raw_page = params.get("page", "1")
    raw_page_size = params.get("page_size", "10")

    if not (isinstance(raw_page, str) and raw_page.isdigit() and
            isinstance(raw_page_size, str) and raw_page_size.isdigit()):
        return 400, {"error": "invalid pagination"}

    page = int(raw_page)
    page_size = int(raw_page_size)

    if page < 1 or not (1 <= page_size <= 100):
        return 400, {"error": "invalid pagination"}

    user_list, total = users.list_users(page, page_size)
    return 200, {
        "users": user_list,
        "page": page,
        "page_size": page_size,
        "total": total
    }

